export async function findLabel(
  orgId: OrgId,
  labelId: LabelId,
): Promise<IssueLabel | null> {
  const row = getDb()
    .select()
    .from(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, labelId)))
    .get();
  return row ? toLabel(row) : null;
}

/**
 * Moves every issue from `sourceLabelId` onto `targetLabelId` and then removes
 * the source label, all in one transaction. Issues that already carry the
 * target keep a single join row. Returns how many issues carried the source.
 */
export async function mergeLabelRows(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  return getDb().transaction((tx) => {
    const sourceIssueIds = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all()
      .map((row) => row.issueId);

    if (sourceIssueIds.length > 0) {
      tx.insert(issueLabels)
        .values(
          sourceIssueIds.map((issueId) => ({
            orgId,
            issueId,
            labelId: targetLabelId,
          })),
        )
        .onConflictDoNothing()
        .run();
    }

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();
    tx.delete(labels)
      .where(
        and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)),
      )
      .run();

    return sourceIssueIds.length;
  });
}

/** Replaces the whole label set of one issue in a single round trip. */

