/**
 * Folds `sourceLabelId` into `targetLabelId`: every issue carrying the source
 * ends up carrying the target instead, then the source label is removed. Takes
 * the same permission as deleting a label, since it removes a label.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  if (input.sourceLabelId === input.targetLabelId) {
    throw new Error("Cannot merge a label into itself");
  }

  const source = await labelRepo.findLabel(input.orgId, input.sourceLabelId);
  requireFound(source, "Label", input.sourceLabelId);
  const target = await labelRepo.findLabel(input.orgId, input.targetLabelId);
  requireFound(target, "Label", input.targetLabelId);

  const issuesRelabelled = await labelRepo.mergeLabelRows(
    input.orgId,
    input.sourceLabelId,
    input.targetLabelId,
  );
  return { label: target, issuesRelabelled };
}

